echo "校验前端页面："
if grep -q 'ModulePlaceholder' frontend/src/views/teacher/AiEvaluation.vue; then
  echo "失败：仍是占位页，请重试"
  exit 1
fi
if ! grep -q 'eval-page' frontend/src/views/teacher/AiEvaluation.vue; then
  echo "失败：未找到 eval-page"
  exit 1
fi
head -8 frontend/src/views/teacher/AiEvaluation.vue
echo "开始强制重建 frontend + backend …"
docker compose build --no-cache frontend backend
docker compose up -d frontend backend
echo "完成。请浏览器强制刷新后再打开：/teacher/ai-evaluation"
